DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_device_operation'' OR ')); END $$;
CREATE TABLE cmd_device_operation_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,operation_rule_id bigint NOT NULL,operation_code text NOT NULL,device_reference text NOT NULL CHECK(btrim(device_reference)<>''),location_id bigint,item_instance_id bigint,task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint NOT NULL,effect smallint NOT NULL,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(location_id,campaign_id) REFERENCES loc_location(location_id,campaign_id),FOREIGN KEY(item_instance_id,campaign_id) REFERENCES inv_item_instance(item_instance_id,campaign_id),FOREIGN KEY(operation_rule_id,operation_code) REFERENCES rule_device_operation(rule_id,operation_code));
